 {id="denadoro64_144",location=144,name="Monte Denadoro, laderas y cascadas",article="el ",house="Monte Denadoro",bounds={0,0,1024,1024},guidance="Laderas y cascadas de Denadoro. El acceso del este lleva a la cornisa, el sureste a la subida oriental y el noroeste al puente y claro. Hay cinco cofres repartidos entre las alturas. Sigue las cornisas y consulta las referencias de acceso; las distancias pueden atravesar agua y precipicios. Caer por una cascada puede cambiar la posición del grupo.",people={},features={{name="Paso a Monte Denadoro, puente y claro",sound="door",box={512,256,528,288}},{name="Paso a Monte Denadoro, cornisa",sound="door",box={1008,368,1024,400}},{name="Paso a Monte Denadoro, subida oriental",sound="door",box={960,624,1008,640}},{name="Cofre",sound="item",box={592,672,608,688},solid=true,treasure=16118982},{name="Cofre",sound="item",box={800,928,816,944},solid=true,treasure=16118986},{name="Cofre",sound="item",box={912,432,928,448},solid=true,treasure=16118990},{name="Cofre",sound="item",box={944,112,960,128},solid=true,treasure=16118994},{name="Cofre",sound="item",box={528,160,544,176},solid=true,treasure=16118998}}},
