 {id="denadoro64_149",location=149,name="Monte Denadoro, tramo del punto de guardado",article="el ",house="Monte Denadoro",bounds={0,0,1024,1024},guidance="Tramo del punto de guardado de Denadoro. El paso norte vuelve al puente y claro; el paso sureste lleva al sector de la cascada y la cueva. El punto de guardado está en la plataforma norte. Usa la escalera de la ladera para cambiar de altura. Hay un cofre y un brillo que puedes examinar. Guardar requiere abrir el menú y elegir una ranura dentro del juego.",people={[16]=false,[18]=false},features={{name="Paso a Monte Denadoro, puente y claro",sound="door",box={960,16,992,32}},{name="Paso a Monte Denadoro, cascada y acceso a la cueva",sound="door",box={1008,448,1024,496}},{name="Cofre",sound="item",box={960,288,976,304},solid=true,treasure=16119030},{name="Punto de guardado",sound="save_point",box={944,168,960,184},entity=16,followEntity=true},{name="Brillo; examina",sound="item",box={784,440,800,456},entity=18,followEntity=true,collected={address=8323172,mask=64}},{name="Escalera de la ladera, extremo inferior",sound="stairs",box={816,224,832,240}},{name="Escalera de la ladera, extremo superior",sound="stairs",box={816,136,832,152}}}},
